<template><main class="article-page"><div class="article-shell page-shell"><button class="article-back" @click="router.push('/notices')"><i class="fa-solid fa-arrow-left"></i> 목록으로</button><div v-if="isLoading" class="community-loading"><span></span><p>공지사항을 불러오고 있습니다.</p></div><article v-else-if="notice"><header><p class="eyebrow">NOTICE</p><h1>{{notice.title}}</h1><time>{{formatDate(notice.date||notice.createdAt)}}</time></header><div class="article-content">{{notice.content}}</div><footer><span>카리나벨 드림</span><button @click="router.push('/notices')">공지사항 목록 <i class="fa-solid fa-arrow-right"></i></button></footer></article><div v-else class="community-empty"><i class="fa-regular fa-file-lines"></i><h2>공지사항을 찾을 수 없습니다.</h2><button @click="router.push('/notices')">목록으로</button></div></div></main></template>
<script setup>import{onMounted,ref}from"vue";import{useRoute,useRouter}from"vue-router";import NoticeService from"@/api/NoticeService";const route=useRoute(),router=useRouter(),notice=ref(null),isLoading=ref(true);const formatDate=value=>value?new Date(value).toLocaleDateString("ko-KR"):"-";onMounted(async()=>{try{notice.value=(await NoticeService.getNoticeDetail(route.params.id,localStorage.getItem("token"))).data}catch(error){console.error(error)}finally{isLoading.value=false}});</script>
<style>.article-page{padding:55px 0 110px;background:var(--color-warm)}.article-shell{max-width:940px}.article-back{margin-bottom:25px;border:0;background:transparent;color:#857b80;font-size:.7rem}.article-back i{margin-right:8px}.article-page article{padding:55px 65px;background:#fff}.article-page article header{padding-bottom:30px;border-bottom:1px solid #342e31}.article-page article h1{margin:12px 0 18px;font-family:Georgia,"Noto Serif KR",serif;font-size:clamp(1.8rem,3.2vw,2.8rem);font-weight:400;line-height:1.4}.article-page time{color:#a0979b;font-size:.65rem}.article-content{min-height:280px;padding:45px 0;color:#5f575b;font-size:.84rem;line-height:2;white-space:pre-line}.article-page article footer{display:flex;justify-content:space-between;padding-top:24px;border-top:1px solid var(--color-line);color:#988e93;font-size:.68rem}.article-page article footer button{border:0;background:transparent;color:var(--color-brand-dark);font-weight:700}.article-page article footer i{margin-left:10px}@media(max-width:600px){.article-page{padding-top:30px}.article-page article{padding:38px 22px}.article-content{padding:35px 0}}
</style>
